<template><div class="settings-page"><nav :aria-label="t('settings.sections')"><a href="#appearance">{{t('settings.theme')}}</a><a href="#network">{{t('settings.mirror_config')}}</a><a href="#maintenance">{{t('settings.cache_management')}}</a></nav><main><SectionCard class="settings-page__section"><ThemeSettings :model-value="isDark" :t="t" @update:model-value="$emit('update:is-dark',$event)"/><LanguageSettings :model-value="locale" :t="t" @update:model-value="$emit('update:locale',$event)"/><FormSection :title="t('settings.path_mode')" :description="t('settings.path_mode_desc')"><label for="path-mode">{{t('settings.path_mode')}}</label><select id="path-mode" data-action="path-mode" :value="pathMode" @change="$emit('update:path-mode',$event.target.value)"><option value="auto">{{t('settings.path_mode_auto')}}</option><option value="shim">{{t('settings.path_mode_shim')}}</option><option value="direct">{{t('settings.path_mode_direct')}}</option></select></FormSection></SectionCard><SectionCard class="settings-page__section"><MirrorSettings :config="mirrorConfig" :results="mirrorTestResults" :locale="locale" :t="t" @update="(...a)=>$emit('mirror-update',...a)" @test="(...a)=>$emit('mirror-test',...a)" @remove="$emit('mirror-remove',$event)" @add="(...a)=>$emit('mirror-add',...a)" @save="$emit('mirror-save')"/><ProxySettings :model-value="proxy" :result="proxyTestResult" :t="t" @update:model-value="$emit('update:proxy',$event)" @test="$emit('proxy-test')" @save="$emit('proxy-save')"/></SectionCard><SectionCard class="settings-page__section"><FormSection :title="t('settings.profile')" :description="t('settings.profile_desc')"><StatusBadge v-if="importResult" :tone="importResult.success?'success':'error'">{{importResult.message}}</StatusBadge><template #actions><button data-action="profile-export" @click="$emit('profile-export')">{{t('settings.profile_export')}}</button><button data-action="profile-import" @click="$emit('profile-import')">{{t('settings.profile_import')}}</button></template></FormSection><FormSection :title="t('settings.self_update')"><StatusBadge v-if="updateInfo" :tone="updateInfo.error?'error':updateInfo.hasUpdate?'warning':'success'">{{updateInfo.error||t(updateInfo.hasUpdate?'update_available':'up_to_date')}}</StatusBadge><template #actions><button data-action="check-update" @click="$emit('check-update')">{{t('btn.check_update')}}</button></template></FormSection></SectionCard><SectionCard class="settings-page__section"><FormSection :title="t('settings.diagnostics')"><AsyncState :empty="!diagResults.length" retry-label=""><ResponsiveDataTable v-if="diagResults.length" :columns="diagColumns" :data="diagResults" row-key="check"/></AsyncState><template #actions><button data-action="run-diagnostics" @click="$emit('run-diagnostics')">{{t('btn.run')}}</button></template></FormSection><CacheSettings :breakdown="cacheBreakdown" :t="t" @clean="$emit('cache-clean',$event)"/></SectionCard></main></div></template>
<script setup>import{computed,h}from'vue';import SectionCard from'../components/SectionCard.vue';import FormSection from'../components/FormSection.vue';import AsyncState from'../components/AsyncState.vue';import ResponsiveDataTable from'../components/ResponsiveDataTable.vue';import StatusBadge from'../components/StatusBadge.vue';import ThemeSettings from'../components/settings/ThemeSettings.vue';import LanguageSettings from'../components/settings/LanguageSettings.vue';import MirrorSettings from'../components/settings/MirrorSettings.vue';import ProxySettings from'../components/settings/ProxySettings.vue';import CacheSettings from'../components/settings/CacheSettings.vue';const p=defineProps({t:{type:Function,required:true},isDark:Boolean,locale:String,pathMode:String,mirrorConfig:Object,mirrorTestResults:Object,proxy:{type:Object,required:true},proxyTestResult:Object,importResult:Object,updateInfo:Object,diagResults:{type:Array,default:()=>[]},cacheBreakdown:Object});defineEmits(['update:is-dark','update:locale','update:path-mode','mirror-update','mirror-test','mirror-remove','mirror-add','mirror-save','update:proxy','proxy-test','proxy-save','profile-export','profile-import','check-update','run-diagnostics','cache-clean']);const diagColumns=computed(()=>[{title:p.t('diag.check'),key:'check',contract:'identity'},{title:p.t('diag.path'),key:'path',contract:'actions'},{title:p.t('diag.status'),key:'ok',contract:'status',render:r=>h(StatusBadge,{tone:r.ok?'success':'error'},()=>p.t(r.ok?'diag.ok':'diag.fail'))}]);</script>
<style scoped>.settings-page{display:grid;grid-template-columns:180px minmax(0,1fr);gap:24px;max-width:1100px;margin:auto}.settings-page nav{position:sticky;top:0;align-self:start;display:grid;gap:6px}.settings-page nav a{padding:8px;color:var(--xdev-text-secondary);text-decoration:none}.settings-page main{display:grid;gap:20px;min-width:0}.settings-page__section{min-width:0}button,select,input{min-height:32px}@media(max-width:760px){.settings-page{grid-template-columns:1fr}.settings-page nav{position:static;display:flex;overflow:auto}.settings-page nav a{white-space:nowrap}}</style>
